const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Lake geometries in Ethiopia
  const lakeLangano = ee.Geometry.Point([38.7, 7.6]).buffer(3000);
  const lakeAbijata = ee.Geometry.Point([38.6, 7.62]).buffer(3000);

  const date = '2022-03-29';
  const startDate = '2022-03-25';
  const endDate = '2022-04-02';

  // Function to mask clouds in Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Get Sentinel-2 imagery
  let colLangano = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lakeLangano)
    .filterDate(startDate, endDate)
    .map(maskS2clouds);

  let colAbijata = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lakeAbijata)
    .filterDate(startDate, endDate)
    .map(maskS2clouds);

  const sizeLangano = colLangano.size().getInfo();
  const sizeAbijata = colAbijata.size().getInfo();

  console.log(`Langano images: ${sizeLangano}, Abijata images: ${sizeAbijata}`);

  if (sizeLangano === 0 || sizeAbijata === 0) {
    console.log("Trying Landsat 8/9 fallback...");
    colLangano = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(lakeLangano)
      .filterDate(startDate, endDate);
    colAbijata = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(lakeAbijata)
      .filterDate(startDate, endDate);

    if (colLangano.size().getInfo() === 0 || colAbijata.size().getInfo() === 0) {
      console.log("No data available for one or both lakes.");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // Composite images
  const imgLangano = colLangano.median();
  const imgAbijata = colAbijata.median();

  // Calculate brownness index (Red/Blue ratio - higher = browner)
  const brownLangano = imgLangano.select('B4').divide(imgLangano.select('B2'));
  const brownAbijata = imgAbijata.select('B4').divide(imgAbijata.select('B2'));

  // Check pixel counts
  const countLangano = brownLangano.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeLangano,
    scale: 1000,
    maxPixels: 1e9
  }).get('B4').getInfo();

  const countAbijata = brownAbijata.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeAbijata,
    scale: 1000,
    maxPixels: 1e9
  }).get('B4').getInfo();

  console.log(`Valid pixels - Langano: ${countLangano}, Abijata: ${countAbijata}`);

  if (countLangano === 0 || countAbijata === 0) {
    console.log("No valid pixels after cloud masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Get mean brownness values
  const brownValLangano = brownLangano.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: lakeLangano,
    scale: 1000,
    maxPixels: 1e9
  }).get('B4').getInfo();

  const brownValAbijata = brownAbijata.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: lakeAbijata,
    scale: 1000,
    maxPixels: 1e9
  }).get('B4').getInfo();

  console.log(`Brownness - Langano: ${brownValLangano}, Abijata: ${brownValAbijata}`);

  if (brownValLangano === null || brownValAbijata === null || 
      isNaN(brownValLangano) || isNaN(brownValAbijata)) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (brownValLangano > brownValAbijata) {
    console.log("Lake Langano is more brown than Lake Abijata.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Lake Langano is NOT more brown than Lake Abijata.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
